window.ScripturaLexicons.BDAG_PART_0013 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athletes-bdag\" data-source=\"BDAG\" data-search=\"ἀθλητής athletes atleta competidor mártir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀθλητής</td><td>Substantivo</td><td>competidor; atleta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athraustos-bdag\" data-source=\"BDAG\" data-search=\"ἄθραυστος athraustos inquebrado intacto número eleitos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄθραυστος</td><td>Adjetivo</td><td>inquebrado; intacto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athroizo-bdag\" data-source=\"BDAG\" data-search=\"ἀθροίζω athroizo reunir ajuntar coletar assembleia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀθροίζω</td><td>Verbo</td><td>reunir; ajuntar; coletar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athumeo-bdag\" data-source=\"BDAG\" data-search=\"ἀθυμέω athumeo desanimar perder ânimo desencorajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀθυμέω</td><td>Verbo</td><td>desanimar-se; perder o ânimo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athumia-bdag\" data-source=\"BDAG\" data-search=\"ἀθυμία athumia desânimo desencorajamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀθυμία</td><td>Substantivo</td><td>desânimo; desencorajamento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-athoos-bdag\" data-source=\"BDAG\" data-search=\"ἀθῷος athoos inocente sem culpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀθῷος</td><td>Adjetivo</td><td>inocente; sem culpa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aigeios-bdag\" data-source=\"BDAG\" data-search=\"αἴγειος aigeios cabra pele cabra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴγειος</td><td>Adjetivo</td><td>de cabra; caprino</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aigialos-bdag\" data-source=\"BDAG\" data-search=\"αἰγιαλός aigialos praia margem costa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰγιαλός</td><td>Substantivo</td><td>praia; margem; costa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aigyptios-bdag\" data-source=\"BDAG\" data-search=\"Αἰγύπτιος Aigyptios egípcio Egito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἰγύπτιος</td><td>Adjetivo/Substantivo</td><td>egípcio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aigyptos-bdag\" data-source=\"BDAG\" data-search=\"Αἴγυπτος Aigyptos Egito simbólico Jerusalém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἴγυπτος</td><td>Nome próprio</td><td>Egito</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aideomai-bdag\" data-source=\"BDAG\" data-search=\"αἰδέομαι aideomai respeitar ter consideração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰδέομαι</td><td>Verbo</td><td>respeitar; ter consideração</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aidios-bdag\" data-source=\"BDAG\" data-search=\"ἀΐδιος aidios eterno perpétuo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀΐδιος</td><td>Adjetivo</td><td>eterno; perpétuo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aidoion-bdag\" data-source=\"BDAG\" data-search=\"αἰδοῖον aidoion partes íntimas genitais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰδοῖον</td><td>Substantivo</td><td>parte íntima; genitais</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aidos-bdag\" data-source=\"BDAG\" data-search=\"αἰδώς aidos modéstia reverência respeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰδώς</td><td>Substantivo</td><td>modéstia; reverência; respeito</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aithiops-bdag\" data-source=\"BDAG\" data-search=\"Αἰθίοψ Aithiops etíope Etiópia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἰθίοψ</td><td>Substantivo/Adjetivo</td><td>etíope</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aithrios-bdag\" data-source=\"BDAG\" data-search=\"αἴθριος aithrios claro brilhante céu claro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴθριος</td><td>Adjetivo</td><td>claro; brilhante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aikia-bdag\" data-source=\"BDAG\" data-search=\"αἰκία aikia maus-tratos tortura tormento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰκία</td><td>Substantivo</td><td>maus-tratos; tortura</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aikisma-bdag\" data-source=\"BDAG\" data-search=\"αἴκισμα aikisma maus-tratos tormento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴκισμα</td><td>Substantivo</td><td>maus-tratos; tormento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aikismos-bdag\" data-source=\"BDAG\" data-search=\"αἰκισμός aikismos maus-tratos punição tortura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰκισμός</td><td>Substantivo</td><td>maus-tratos; punição</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ailamites-bdag\" data-source=\"BDAG\" data-search=\"Αἰλαμίτης Ailamites elamita remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἰλαμίτης</td><td>Remissão</td><td>ver Ἐλαμ(ε)ίτης</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ailouros-bdag\" data-source=\"BDAG\" data-search=\"αἴλουρος ailouros gato felino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴλουρος</td><td>Substantivo</td><td>gato</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-athletes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀθλητής</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦athlētḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Píndaro [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀεθλητής\" data-meanings=\"competidor; forma antiga\">ἀεθλητής</span>]; inscrições, papiros, 4 Macabeus, TestJob, Fílon; Jos., <em>Ant.</em> 13, 327; 17, 259; empréstimo no rabínico.) <strong>Competidor, atleta</strong>; em nossa literatura apenas figuradamente (desde Górgias [E. Scheel, <em>De Gorgianae Disciplinae Vestigiis</em>, diss. Rostock 1890, 13]; também Diod S 9, 1, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. πάσης ἀρετῆς\" data-meanings=\"atleta de toda virtude\">ἀ. πάσης ἀρετῆς</span>; Dio Chrys. 2, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 6.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">17.15 s.</a>), dos mártires: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἔγγιστα γενόμενοι ἀ.\" data-meanings=\"os atletas que estiveram mais próximos\">οἱ ἔγγιστα γενόμενοι ἀ.</span> 1 Cl 5:1. De alguém experimentado no sofrimento: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τέλειος ἀ.\" data-meanings=\"atleta perfeito\">τέλειος ἀ.</span> IPol 1:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέγας ἀ.\" data-meanings=\"grande atleta\">μέγας ἀ.</span> 3:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεοῦ ἀ.\" data-meanings=\"atleta de Deus\">θεοῦ ἀ.</span> 2:3. Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀθλέω\" data-meanings=\"competir\">ἀθλέω</span>.\n</p></section></article><article id=\"entry-athraustos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄθραυστος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦áthraustos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Eurípides e outros; SIG 970, 15; Sb 8960, 20 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. βίος\" data-meanings=\"vida inquebrada\">ἄ. βίος</span>) <strong>inquebrado, intacto</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. διαφυλάσσειν τὸν ἀριθμὸν τῶν ἐκλεκτῶν\" data-meanings=\"preservar intacto o número dos eleitos\">ἄ. διαφυλάσσειν τὸν ἀριθμὸν τῶν ἐκλεκτῶν</span> 1 Cl 59:2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θραύω\" data-meanings=\"quebrar\">θραύω</span>.\n</p></section></article><article id=\"entry-athroizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀθροίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦athroízō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀθροίσω; 1 aor. ἤθροισα · pass. 1 aor. ἠθροίσθητε, ἠθροίσθησαν; pf. ptc. ἠθροισμένος</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nDenominativo de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀθρόος\" data-meanings=\"em multidões; reunido\">ἀθρόος</span> (trágicos, Heródoto e outros; OGI 764, 9; UPZ 12, 42 [158 a.C.]; LXX; Fílon, <em>De Jos.</em> 158; Jos., <em>Ant.</em> 3, 300 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Μωϋσῆς εἰς ἐκκλησίαν ἀθροίζει τὸ πλῆθος\" data-meanings=\"Moisés reúne a multidão em assembleia\">Μωϋσῆς εἰς ἐκκλησίαν ἀθροίζει τὸ πλῆθος</span>; Just., <em>D.</em> 109, 3 [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀθροίσω\" data-meanings=\"reunirei\">ἀθροίσω</span> por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰσδέξομαι\" data-meanings=\"acolherei\">εἰσδέξομαι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MIC.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mq 4.6</a>]). <strong>Fazer estar junto num grupo, coletar, reunir</strong>; passivo com sentido ativo, <strong>reunir-se</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.33</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀθρόος\" data-meanings=\"reunido\">ἀθρόος</span>. M-M.\n</p></section></article><article id=\"entry-athumeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀθυμέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦athuméō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. 3 sg. ἠθύμησεν</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Ésquilo; Thuc. 5, 91, 1; PAmh 37, 7; 10 [séc. II a.C.]; PGiss 79 III, 11; LXX, Fílon; Jos., <em>Bell.</em> 6, 94; <em>Ant.</em> 9, 87; Just., <em>D.</em> 107, 3.) <strong>Ficar desanimado a ponto de perder a motivação, desanimar-se, perder o ânimo, ficar abatido</strong>; de filhos (Hyperid., Fgm. 144): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα μὴ ἀθυμῶσιν\" data-meanings=\"para que não desanimem\">ἵνα μὴ ἀθυμῶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.21</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θυμός\" data-meanings=\"ânimo; disposição\">θυμός</span>. M-M.\n</p></section></article><article id=\"entry-athumia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀθυμία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦athumía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Sófocles, Heródoto e outros; UPZ 19, 14 [163 a.C.]; LXX; TestSol 1:3 L; TestAbr A 20, p. 103, 4 [Stone p. 54], de perda de energia; Fílon; Jos., <em>Bell.</em> 3, 182; <em>Ant.</em> 12, 35; <em>C. Ap.</em> 1, 236.) <strong>Desânimo a ponto de perder a motivação, desencorajamento</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἀ. βάλλειν τινά\" data-meanings=\"lançar alguém no desânimo\">εἰς ἀ. βάλλειν τινά</span> = “mergulhar alguém no desânimo”, 1 Cl 46:9 (compare Aeschin. 3, 177 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὴν ἐσχάτην ἀ. ἐμβαλεῖν\" data-meanings=\"lançar no extremo desânimo\">εἰς τὴν ἐσχάτην ἀ. ἐμβαλεῖν</span>). Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀθυμέω\" data-meanings=\"desanimar-se\">ἀθυμέω</span>.\n</p></section></article><article id=\"entry-athoos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀθῷος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦athō̂os⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θωή\" data-meanings=\"pena; punição\">θωή</span>; Eurípides+; SIG 1157, 59; 1217, 6; PTebt 44, 28; 800, 38 [ambos séc. II a.C.]; LXX, Fílon; Jos., <em>Ant.</em> 4, 271; 8, 15; Just.; Mel., <em>P.</em> 74, 542.) <strong>Inocente.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα ἀ.\" data-meanings=\"sangue inocente\">αἷμα ἀ.</span> (frequente na LXX, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.27.25\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 27.25</a>; Fílon, <em>Spec. Leg.</em> 1, 204; TestLevi 16:3; TestZeb 2:2; Mel., <em>P.</em> 73), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.4</a>; GJs 14:1; 23:3. De pessoas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. εἶναι ἀπό τινος\" data-meanings=\"ser inocente de alguém/algo\">ἀ. εἶναι ἀπό τινος</span> (B-D-F §182, 3; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.41\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 5.19</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.24</a>; 1 Cl 59:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετὰ ἀνδρὸς ἀθῴου ἀ. ἔσῃ\" data-meanings=\"com o homem inocente serás inocente\">μετὰ ἀνδρὸς ἀθῴου ἀ. ἔσῃ</span> 1 Cl 46:3 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 17.26</a>). Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκαιος\" data-meanings=\"justo\">δίκαιος</span> v. 4 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 23.7</a>); <strong>sem culpa</strong> do que dá esmola, na medida em que cumpriu o mandamento, D 1:5; Hm 2:6. — B. 1446. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θωή\" data-meanings=\"pena\">θωή</span>. M-M.\n</p></section></article><article id=\"entry-aigeios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴγειος</h1><div class=\"entry-meta\"><span class=\"greek\">εία, ειον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aígeios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴξ\" data-meanings=\"cabra\">αἴξ</span>; Homero e outros; inscrições, papiros, LXX; Jos., <em>Ant.</em> 3, 102.) <strong>De cabra, caprino.</strong> Da vestimenta dos profetas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν αἰγείοις δέρμασιν\" data-meanings=\"em peles de cabra\">ἐν αἰγείοις δέρμασιν</span> (PCairZen 60, 8 [séc. III a.C.]; PFay 107, 2 s. e outros, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δέρμα αἴγειον\" data-meanings=\"pele de cabra\">δέρμα αἴγειον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.37</a>; 1 Cl 17:1 (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μηλωταί\" data-meanings=\"peles de ovelha\">μηλωταί</span>). Da vestimenta do anjo da punição, Hs 6, 2, 5; do pastor, Hv 5:1. — M-M.\n</p></section></article><article id=\"entry-aigialos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγιαλός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aigialós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Margem, praia</strong> (Homero e outros; sobretudo do mar, como OGI 199, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 5.17</a> A; Fílon, <em>Aet. M.</em> 42; Jos., <em>Ant.</em> 14, 292; TestZeb 6:3; TestSol 2:5; mas também de lagos, por exemplo PTebt 79 [148 a.C.]; 82; 83; PFay 82, 3; Jos., <em>Bell.</em> 3, 521 [lago de Genesaré]). Em geral: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑστάναι ἐπὶ τὸν αἰ.\" data-meanings=\"estar sobre a praia\">ἑστάναι ἐπὶ τὸν αἰ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑστάναι εἰς τὸν αἰ.\" data-meanings=\"estar na praia\">ἑστάναι εἰς τὸν αἰ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.4</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβιβάζειν ἐπὶ τὸν αἰ.\" data-meanings=\"trazer para a praia\">ἀναβιβάζειν ἐπὶ τὸν αἰ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.48</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.5</a>. Adequada para encalhar navios: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κόλπον ἔχοντα αἰ.\" data-meanings=\"uma baía que tinha praia\">κόλπον ἔχοντα αἰ.</span> = “uma baía com uma boa praia”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.39</a> (compare X., <em>An.</em> 6, 4, 4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λιμὴν αἰγιαλὸν ἔχων\" data-meanings=\"porto que possui praia\">λιμὴν αἰγιαλὸν ἔχων</span>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατέχειν εἰς τ. αἰ.\" data-meanings=\"dirigir-se para a praia\">κατέχειν εἰς τ. αἰ.</span> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατέχω\" data-meanings=\"dirigir-se; manter\">κατέχω</span> 7), v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">40</a>. — B. 32. DELG. M-M.\n</p></section></article><article id=\"entry-aigyptios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγύπτιος</h1><div class=\"entry-meta\"><span class=\"greek\">ία, ιον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Aigúptios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+.) <strong>Egípcio.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ Αἰ. εὐαγγέλιον\" data-meanings=\"o Evangelho Egípcio\">τὸ Αἰ. εὐαγγέλιον</span> Kl. T. 83, p. 15, 8. — Como substantivo apenas como nome nacional, <strong>o egípcio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.23</a> D (ambos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.12</a>; compare Ezk. Trag. 93 [Eus., <em>PE</em> 9, 28]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.28</a>; 1 Cl 4:10 (ambos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.14</a>). Sua sabedoria, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.22</a>. De certo egípcio não nomeado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.38</a> (compare Jos., <em>Ant.</em> 20, 171; 172). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ Αἰγύπτιοι\" data-meanings=\"os egípcios\">οἱ Αἰγύπτιοι</span>, do faraó do Êxodo e seu exército, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.29</a>. Da nação como um todo, B 9:6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ κατ’ Αἰγυπτίους εὐαγγ.\" data-meanings=\"o Evangelho segundo os Egípcios\">τὸ κατ’ Αἰγυπτίους εὐαγγ.</span> Kl. T. 83, p. 4, 14; 15, 19; 16, 5; 9. — M-M.\n</p></section></article><article id=\"entry-aigyptos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴγυπτος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Aíguptos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; exceto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.11</a>; 1 Cl 25:3; Just., <em>D.</em> 131, 3; Mel., <em>P.</em> 11, 74; 60, 439 [em ambos Bodm. contra Ch.], sempre sem artigo [W-S. §18, 5d; B-D-F §261, 7].) <strong>Egito.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.13 s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HOS.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Os 11.1</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">7.9 ss.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">34</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 3.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">10</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">11.26 s.</a>; 1 Cl 4:10; 25:3; 51:5. Mais plenamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.36</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 7.3</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">13.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.9</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.38.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 38.32</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 5</a>; 1 Cl 51:5 v.l.; 53:2; B 4:8; 14:3 (os três últimos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.32.7\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 32.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 9.12</a>); B 2:7 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 7.22</a>). País por metonímia para seu povo, 1 Cl 17:5. — Como nome simbólico, com Sodoma, de uma cidade; a adição <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπου καὶ ὁ κύριος αὐτῶν ἐσταυρώθη\" data-meanings=\"onde também o Senhor deles foi crucificado\">ὅπου καὶ ὁ κύριος αὐτῶν ἐσταυρώθη</span> mostra que Jerusalém é pretendida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11.8</a>.\n</p></section></article><article id=\"entry-aideomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aidéomai⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. ᾐδέσθην; 1 aor. mid. ᾐδέσατο</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; veja Nägeli 57; 1 aor. médio <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾐδέσατο\" data-meanings=\"respeitou; envergonhou-se\">ᾐδέσατο</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 9.3</a>, “envergonhar-se”.) Médio-passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾐδέσθην\" data-meanings=\"respeitei\">ᾐδέσθην</span> <strong>respeitar</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινά\" data-meanings=\"alguém\">τινά</span> (Calino [séc. VII a.C.], Fgm. 1, 2 Diehl²; Apollon. Rhod. 4, 796 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐμέ\" data-meanings=\"a mim\">ἐμέ</span>, isto é, Hera; Diod S 5, 31, 5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἄρης αἰδεῖται τὰς Μούσας\" data-meanings=\"Ares respeita as Musas\">Ἄρης αἰδεῖται τὰς Μούσας</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς προηγουμένους\" data-meanings=\"os que vos dirigem\">τοὺς προηγουμένους</span> 1 Cl 21:6; <strong>ter consideração por</strong> (PGissUniv 21, 8; Appian, <em>Maced.</em> 9 §6; Dio Chrys. 71 [21], 13): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰδέσθητί σου τὴν ἡλικίαν\" data-meanings=\"tem consideração por tua idade\">αἰδέσθητί σου τὴν ἡλικίαν</span> MPol 9:2 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 5.7</a>; Fílon, <em>Spec. Leg.</em> 2, 238). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴδομαι\" data-meanings=\"respeitar; reverenciar\">αἴδομαι</span>. M-M. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰδώς\" data-meanings=\"respeito; modéstia\">αἰδώς</span>.\n</p></section></article><article id=\"entry-aidios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐδιος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aḯdios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀεί\" data-meanings=\"sempre\">ἀεί</span>; Hinos Homéricos, Hesíodo e outros; inscrições; PSI 1422, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 10.15</a>; palavra favorita em Fílon; Jos., <em>Ant.</em> 4, 178; 17, 152; Just., <em>A</em> II, 11, 5; Tat. 14, 2; Ath.; Mel., <em>P.</em> 2 s., 20.) <strong>Eterno.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἀ. αὐτοῦ δύναμις\" data-meanings=\"seu poder eterno\">ἡ ἀ. αὐτοῦ δύναμις</span> — de Deus —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.20</a> (Zoroastro em Fílon de Biblos, 790 Fgm. 4, 52 Jac. [Eus., <em>PE</em> 1, 10, 52]; 58ª carta de Apolônio de Tiana [Philostrat. I 360, 29 K.]; SibOr 5, 66 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεὸς ἀ.\" data-meanings=\"Deus eterno\">θεὸς ἀ.</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζωή\" data-meanings=\"vida\">ζωή</span> (Fílon, <em>Fug.</em> 97; Tat. 14, 2), IEph 19:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δεσμοῖς ἀ.\" data-meanings=\"com cadeias eternas\">δεσμοῖς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 6</a> (PGM 4, 1466 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πυλωρὲ κλείθρων ἀϊδίων\" data-meanings=\"guardião das chaves eternas\">πυλωρὲ κλείθρων ἀϊδίων</span>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰών\" data-meanings=\"era; eternidade\">αἰών</span>. M-M. TW.\n</p></section></article><article id=\"entry-aidoion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδοῖον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aidoîon⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰδώς\" data-meanings=\"modéstia; respeito\">αἰδώς</span>; substantivado do adjetivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰδοῖος, α, ον\" data-meanings=\"respeitável; pudendo\">αἰδοῖος, α, ον</span>, Homero e outros; PSI 1180, 53 [séc. II d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 23.20</a>; Tat. 8:2; Ath. No singular, Heródoto e outros; UPZ 77 col. 2, 29 [séc. II a.C.]; Josefo.) <strong>Parte(s) íntima(s), genitais</strong>, Papias 3:2 (veja o verbete <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀηδής\" data-meanings=\"desagradável; odioso\">ἀηδής</span>).\n</p></section></article><article id=\"entry-aidos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδώς</h1><div class=\"entry-meta\"><span class=\"greek\">οῦς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aidṓs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Sobre a etimologia, veja o fim do verbete em DGE; Homero+; Epict.; OGI 507, 8; PCairMasp 295 III, 22 [séc. V d.C.]; LXX; TestJud 14:7; Jos., <em>Bell.</em> 2, 325; SibOr 1, 35; Ath. 30, 2.) O termo expressa o oposto de considerar ou tratar algo de modo comum ou ordinário; implica respeito pela convenção.\n<span class=\"sense-number\">1.</span> <strong>Modéstia</strong>, de mulheres (Diod S 13, 55, 4). Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σωφροσύνη\" data-meanings=\"moderação; decoro\">σωφροσύνη</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετὰ αἰ.\" data-meanings=\"com modéstia\">μετὰ αἰ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2.9</a> (compare Jos., <em>Ant.</em> 2, 52; AcPl Ox 6 [Aa I 241, 15]).\n<span class=\"sense-number\">2.</span> <strong>Reverência, respeito</strong> (Píndaro e outros; Plut., <em>Timol.</em> 238 [7, 1]; Jos., <em>Ant.</em> 6, 262; Iren. 1, 8, 2 [Harv. I 70, 1], com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐλάβεια\" data-meanings=\"reverência; temor\">εὐλάβεια</span>, como Fílon, <em>Leg. ad Gai.</em> 352; Ath. 30, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.28</a> v.l. (compare Appian, <em>Bell. Civ.</em> 1, 71 §331 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰδὼς θεῶν\" data-meanings=\"reverência aos deuses\">αἰδὼς θεῶν</span>). — R. Schultz, <em>ΑΙΔΩΣ</em>, diss. Rostock 1910; C. E. von Erffa, <em>ΑΙΔΩΣ</em>, <em>Philol. Suppl.</em> 30, 2, 1937; D. Cairns, <em>Aidōs</em>, 1993. — B. 1141. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴδομαι\" data-meanings=\"respeitar; reverenciar\">αἴδομαι</span>. M-M (sem papiros). TW. Spicq.\n</p></section></article><article id=\"entry-aithiops-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθίοψ</h1><div class=\"entry-meta\"><span class=\"greek\">οπος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Aithíops⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; inscrições, papiros, LXX; ParJer 3:12; ApcMos 35; Fílon, <em>Deus Imm.</em> 174; Josefo; EpArist 13; SibOr.) <strong>Etíope</strong> (veja Heródoto, OxfT, índice s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Αἰθίοπες\" data-meanings=\"etíopes\">Αἰθίοπες</span>; sobre a compleição, veja Hdt. 2, 22, 3): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βασίλισσα Αἰθιόπων\" data-meanings=\"rainha dos etíopes\">βασίλισσα Αἰθιόπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.27</a>; como adjetivo com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνήρ\" data-meanings=\"homem\">ἀνήρ</span> (Stephan. Byz. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Αἰθίοψ\" data-meanings=\"etíope\">Αἰθίοψ</span>, segundo Favorino), no mesmo versículo; a etnicidade é o componente principal, compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὴρ Ἰουδαῖος\" data-meanings=\"homem judeu\">ἀνὴρ Ἰουδαῖος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.3</a>. — Para bibliografia, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Κανδάκη\" data-meanings=\"Candace\">Κανδάκη</span>.\n</p></section></article><article id=\"entry-aithrios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθριος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aíthrios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero; <em>Hymns Apollo</em> 433; Heráclito Fgm. 120 Diels; Heródoto; LXX; TestJob 24:3; Josefo.) <strong>Claro, brilhante</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰθρίου ὄντος τοῦ ἀέρος\" data-meanings=\"estando claro o céu\">αἰθρίου ὄντος τοῦ ἀέρος</span> = “embora o céu estivesse claro”, AcPl Ha 5, 6. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴθω\" data-meanings=\"arder; brilhar\">αἴθω</span>.\n</p></section></article><article id=\"entry-aikia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκία</h1><div class=\"entry-meta\"><span class=\"greek\">ίας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aikía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"-εία\" data-meanings=\"variante de terminação\">-εία</span>, com grafias variantes em Ésquilo e outros; papiros; 2 e 3 Macabeus; Josefo; Just., <em>D.</em> 34, 8; Ath., <em>R.</em> 71, 9 e outros.) <strong>Maus-tratos, tortura</strong>, com morte dolorosa (Andoc. 1, 138; Polyb. 1, 85, 2; Ps.-Pla., <em>Axioch.</em> 372a), 1 Cl 6:1 (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βάσανος\" data-meanings=\"tormento\">βάσανος</span>; compare Jos., <em>Bell.</em> 3, 321). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς αἰ. περιβαλεῖν\" data-meanings=\"submeter à tortura\">εἰς αἰ. περιβαλεῖν</span> (Lghtf. conjectura <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παραβαλεῖν\" data-meanings=\"entregar; expor\">παραβαλεῖν</span>), “torturar”, 1 Cl 45:7 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 6.26</a>; EpArist 208). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰκίαις περιπίπτειν\" data-meanings=\"cair em torturas\">αἰκίαις περιπίπτειν</span>, “ser torturado, atormentado”, 1 Cl 51:2. — Frisk s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀϊκής\" data-meanings=\"ultrajante; cruel\">ἀϊκής</span>.\n</p></section></article><article id=\"entry-aikisma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴκισμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aíkisma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Trágicos e outros; Lísias 6, 26; Pollux 6, 183.) <strong>Maus-tratos, tormento</strong>, 1 Cl 6:2; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μάστιγες\" data-meanings=\"açoites\">μάστιγες</span>, 17:5. — Frisk s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀϊκής\" data-meanings=\"ultrajante; cruel\">ἀϊκής</span>.\n</p></section></article><article id=\"entry-aikismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκισμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aikismós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Ctesias [400 a.C.]; Pollux 8, 79; papiros, LXX; Just., <em>A</em> II, 12, 4.) <strong>Maus-tratos</strong> (PHal 1, 118 [séc. III a.C.]; 2 e 4 Macabeus); com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κόλασις\" data-meanings=\"punição\">κόλασις</span>, <strong>punição</strong> (Plut., <em>Mor.</em> 8f): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς αἰ. τιθέναι\" data-meanings=\"submeter a maus-tratos/punição\">εἰς αἰ. τιθέναι</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰκίζειν\" data-meanings=\"maltratar; punir\">αἰκίζειν</span>, 1 Cl 11:1. — Frisk s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀϊκής\" data-meanings=\"ultrajante; cruel\">ἀϊκής</span>.\n</p></section></article><article id=\"entry-ailamites-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰλαμίτης</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Ailamítēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nVeja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἐλαμ(ε)ίτης\" data-meanings=\"elamita\">Ἐλαμ(ε)ίτης</span>.\n</p></section></article><article id=\"entry-ailouros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴλουρος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aílouros⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Hdt. 2, 66 [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰέλουρος\" data-meanings=\"gato; variante antiga\">αἰέλουρος</span>].) <strong>Gato</strong> (Heródoto, Aristóteles; Diod S 20, 58, 2; Ptolem., <em>Apotel.</em> 3, 9, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κυνῶν ἢ αἰλούρων\" data-meanings=\"de cães ou gatos\">κυνῶν ἢ αἰλούρων</span>; Aelian; Plut., <em>Mor.</em> 144c; Cyranides p. 59, 13 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. ἤτοι κάττα\" data-meanings=\"gato, isto é, katta\">αἴ. ἤτοι κάττα</span>; EpJer 21), PtK 2 p. 14, 19. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰέλουρος\" data-meanings=\"gato\">αἰέλουρος</span>.\n</p></section></article>"};
